with.code:
const env = $json;
const b = env.budget || {};
const cap = b.cap_minor_units ?? null;
const spent = b.spent_minor_units ?? 0;
const estimate = env.payload?.estimate_minor_units ?? 0;
const soft = (b.soft_limit_pct ?? 0.8);

let decision = 'allow', reason = 'within_budget', tier_cap = env.policy?.model_tier_cap || 'frontier';

if (cap !== null) {
  const projected = spent + estimate;
  if (projected > cap) { decision = 'deny'; reason = 'BUDGET_EXCEEDED'; }
  else if (projected > cap * soft) {
    const onSoft = b.on_soft_limit || 'downgrade_tier';
    if (onSoft === 'downgrade_tier') { decision = 'downgrade'; reason = 'soft_limit'; tier_cap = { frontier: 'standard', standard: 'small', small: 'nano', nano: 'nano' }[tier_cap] || 'small'; }
    else if (onSoft === 'halt_optional' && env.payload?.optional) { decision = 'deny'; reason = 'soft_limit_optional_halted'; }
    else { decision = 'allow'; reason = 'soft_limit_notify'; }
  }
}

return [{ json: { decision, reason, tier_cap, projected_minor_units: spent + estimate, cap_minor_units: cap } }];
